basicCode.vanilla:
import { createContextDisplay } from '@/components/ui/context-display';

createContextDisplay({
  usage: { input: 18000, output: 7000, limit: 32000 },
  form: 'ring',
  labels: rotulos,
});

basicCode.react:
import { ContextDisplay } from "@/components/ui/context-display";

<ContextDisplay
  usage={{ input: 18000, output: 7000, limit: 32000 }}
  form="ring"
  labels={rotulos}
/>

withLabelsCode.web:
// O nome da medida, a palavra de cada nível, a unidade contada, e o que dizer
// quando o teto não é conhecido.
//
// A palavra do nível aparece SEMPRE que há teto, inclusive com folga: uma peça
// que só falasse quando a notícia é ruim deixaria a boa notícia indistinguível
// de uma medição que não chegou.
const rotulos = {
  title: 'Uso da janela de contexto',
  level: {
    normal: 'Com folga',
    warning: 'Perto do limite',
    critical: 'No limite',
  },
  of: 'de',
  unit: 'tokens',
  unbounded: 'Sem teto conhecido',
};

extensibilityCode.web:
// O LIMIAR É DECISÃO DO PRIMITIVO, e a comparação é EXATA:
budgetLevel({ input: 749, output: 0, limit: 1000 });  // 'normal'
budgetLevel({ input: 750, output: 0, limit: 1000 });  // 'warning'  — três quartos em ponto
budgetLevel({ input: 900, output: 0, limit: 1000 });  // 'critical'

// SEM TETO NÃO HÁ FRAÇÃO, e a ausência sai como ausência — nunca como zero:
usedPercent({ input: 800, output: 400 });             // null
budgetLevel({ input: 800, output: 400 });             // null

// O número é travado nas duas pontas, porque é ele que se lê em voz:
usedPercent({ input: 999, output: 0, limit: 1000 });  // 99, e não 100
usedPercent({ input: 1, output: 0, limit: 10000 });   // 1, e não 0

customizationCode.web:
.nds-context-display {
  max-inline-size: 24rem;
}

/* O medidor é REFORÇO, e não a pista: a palavra do nível ao lado é o que
   descreve. Mexer no anel não muda o que chega a quem ouve. */
.nds-context-display-ring {
  inline-size: var(--size-default);
  block-size: var(--size-default);
}

